public record Order(String id, String sku, int quantity) {
    public Order {                       // compact constructor: invariants at the boundary
        Objects.requireNonNull(id);
        if (quantity <= 0) throw new IllegalArgumentException("qty");
        sku = sku.strip().toUpperCase();
    }
    public static Order from(LegacyOrder l) { return new Order(l.name(), l.sku(), l.qty()); }
}

